import os
from flask import Flask
from dotenv import load_dotenv

# Load .env and .env.local (generated by Neon)
load_dotenv()
load_dotenv(os.path.join(os.path.dirname(__file__), "..", ".env.local"))

def create_app():
    app = Flask(__name__)
    
    # Secret Key
    app.secret_key = os.environ.get("SECRET_KEY", "dev-secret-for-swapskills-local")

    # Database Configuration
    # Uses DATABASE_URL provided by Neon Postgres
    database_url = os.environ.get("DATABASE_URL")
    if database_url:
        # Standardize PostgreSQL dialect for SQLAlchemy
        if database_url.startswith("postgres://"):
            database_url = database_url.replace("postgres://", "postgresql+psycopg2://", 1)
        elif database_url.startswith("postgresql://") and not database_url.startswith("postgresql+"):
            database_url = database_url.replace("postgresql://", "postgresql+psycopg2://", 1)
        # Remove unsupported channel_binding if present
        database_url = database_url.replace("&channel_binding=require", "").replace("channel_binding=require&", "").replace("?channel_binding=require", "")
        app.config["SQLALCHEMY_DATABASE_URI"] = database_url
    else:
        # Fallback to SQLite (on Vercel/serverless use /tmp which is writable)
        base_dir = "/tmp" if os.environ.get("VERCEL") or os.environ.get("AWS_LAMBDA_FUNCTION_NAME") else os.path.abspath(os.path.join(app.root_path, "..", "instance"))
        try:
            os.makedirs(base_dir, exist_ok=True)
        except Exception:
            base_dir = "/tmp"
            os.makedirs(base_dir, exist_ok=True)
        db_path = os.path.join(base_dir, "swapskills.db")
        app.config["SQLALCHEMY_DATABASE_URI"] = f"sqlite:///{db_path}"

    app.config["SQLALCHEMY_TRACK_MODIFICATIONS"] = False

    # Library File Upload Configuration
    # Max file upload size: default 500MB (configurable via MAX_CONTENT_LENGTH_MB)
    max_mb = int(os.environ.get("MAX_CONTENT_LENGTH_MB", 500))
    app.config["MAX_CONTENT_LENGTH"] = max_mb * 1024 * 1024
    
    upload_folder = os.environ.get("UPLOAD_FOLDER")
    if not upload_folder:
        if os.environ.get("VERCEL") or os.environ.get("AWS_LAMBDA_FUNCTION_NAME"):
            upload_folder = "/tmp/uploads/library"
        else:
            upload_folder = os.path.abspath(os.path.join(app.root_path, "static", "uploads", "library"))
    try:
        os.makedirs(upload_folder, exist_ok=True)
    except Exception:
        upload_folder = "/tmp/uploads/library"
        os.makedirs(upload_folder, exist_ok=True)
    app.config["LIBRARY_UPLOAD_FOLDER"] = upload_folder

    # Initialize SQLAlchemy
    from .models import db
    try:
        db.init_app(app)
        with app.app_context():
            db.create_all()
    except Exception as db_err:
        print(f"⚠️ Primary DB initialization notice ({db_err}). Falling back to local store.")
        # Fallback to local SQLite if remote PostgreSQL driver is missing or failed on cold start
        sqlite_fallback = "/tmp/swapskills_fallback.db" if os.environ.get("VERCEL") or os.environ.get("AWS_LAMBDA_FUNCTION_NAME") else os.path.abspath(os.path.join(app.root_path, "..", "instance", "swapskills.db"))
        app.config["SQLALCHEMY_DATABASE_URI"] = f"sqlite:///{sqlite_fallback}"
        try:
            db.init_app(app)
            with app.app_context():
                db.create_all()
        except Exception:
            pass

    # Register routes blueprint
    from .routes import main
    app.register_blueprint(main)
    
    return app
